DROP VIEW "vritti_core"."inventory_stock_levels";--> statement-breakpoint
CREATE VIEW "vritti_core"."inventory_stock_levels" AS (select COALESCE("q"."inventory_item_id", "vritti_core"."inventory_item_locations"."inventory_item_id") as "inventory_item_id", COALESCE("q"."location_id", "vritti_core"."inventory_item_locations"."location_id") as "location_id", CAST(COALESCE("q"."stocked", 0) AS TEXT) as "stocked_quantity", CAST(COALESCE("q"."reserved", 0) AS TEXT) as "reserved_quantity", CAST(COALESCE("q"."available", 0) AS TEXT) as "available_quantity", "vritti_core"."inventory_item_locations"."reorder_level" from (select "inventory_item_id", "location_id", SUM("quantity") as "stocked", SUM("reserved_quantity") as "reserved", SUM("quantity" - "reserved_quantity") as "available" from "vritti_core"."inventory_item_quants" group by "vritti_core"."inventory_item_quants"."inventory_item_id", "vritti_core"."inventory_item_quants"."location_id") "q" full join "vritti_core"."inventory_item_locations" on "q"."inventory_item_id" = "vritti_core"."inventory_item_locations"."inventory_item_id" AND "q"."location_id" = "vritti_core"."inventory_item_locations"."location_id");